examples.template:
MonarchButton({{trigger}}, variant: .danger) { isShown = true }
    .sheet(isPresented: $isShown) {
        VStack(alignment: .leading, spacing: 0) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                HStack(alignment: .firstTextBaseline) {
                    Text({{title}}).monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
                    Spacer()
                    Button { isShown = false } label: { Image(systemName: "xmark") }
                        .buttonStyle(.plain)
                        .foregroundStyle(theme.colors.textMuted)
                        .accessibilityLabel("Close")
                }
                Text({{description}}).monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                Text({{body}}).monarchTextStyle(.body).padding(.top, theme.spacing.space2)
            }
            .padding(theme.spacing.space6)
            Divider()
            HStack(spacing: theme.spacing.space2) {
                Spacer()
                MonarchButton({{cancel}}, variant: .secondary) { isShown = false }
                MonarchButton({{confirm}}, variant: .danger) { isShown = false }
            }
            .padding(theme.spacing.space4)
            .background(theme.colors.bgSubtle.ignoresSafeArea(edges: .bottom))
        }
        .presentationDetents([.height(280)])
        .presentationBackground(theme.colors.bgSurface)
        .presentationCornerRadius(12)
    }

examples.code:
MonarchButton("Delete project", variant: .danger) { isShown = true }
    .sheet(isPresented: $isShown) {
        VStack(alignment: .leading, spacing: 0) {
            VStack(alignment: .leading, spacing: theme.spacing.space3) {
                HStack(alignment: .firstTextBaseline) {
                    Text("Delete project?").monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
                    Spacer()
                    Button { isShown = false } label: { Image(systemName: "xmark") }
                        .buttonStyle(.plain)
                        .foregroundStyle(theme.colors.textMuted)
                        .accessibilityLabel("Close")
                }
                Text("This removes all tasks and sprints. It cannot be undone.").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                Text("Type the project name to confirm.").monarchTextStyle(.body).padding(.top, theme.spacing.space2)
            }
            .padding(theme.spacing.space6)
            Divider()
            HStack(spacing: theme.spacing.space2) {
                Spacer()
                MonarchButton("Cancel", variant: .secondary) { isShown = false }
                MonarchButton("Delete", variant: .danger) { isShown = false }
            }
            .padding(theme.spacing.space4)
            .background(theme.colors.bgSubtle.ignoresSafeArea(edges: .bottom))
        }
        .presentationDetents([.height(280)])
        .presentationBackground(theme.colors.bgSurface)
        .presentationCornerRadius(12)
    }

MonarchButton("Edit the profile", variant: .primary) { isEditing = true }
    .sheet(isPresented: $isEditing) {
        NavigationStack {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                MonarchTextField("Name", text: $name)
                Spacer()
            }
            .padding(theme.spacing.space4)
            .background(theme.colors.bgCanvas)
            .navigationTitle("Edit profile")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { isEditing = false }
                }
                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") { isEditing = false }
                }
            }
        }
    }

examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isEditing = false
@State private var name = "Ada Lovelace"
